let merchProducts=[];
function initializeMerch(){merchProducts=[
{id:'tee',name:P('The Heritage Tee','تيشيرت التراث'),price:30,desc:P('An ivory tee with a restrained burgundy chest print: Sudan, Meroë pyramids, and SSO UofA.','تيشيرت عاجي بطباعة عنابية بسيطة على الصدر تجمع السودان وأهرامات مروي واسم المنظمة.'),sizes:['XS','S','M','L','XL','2XL']},
{id:'hoodie',name:P('The Meroë Hoodie','هودي مروي'),price:65,desc:P('A deep burgundy hoodie with a cream heritage graphic on the back. From home to campus.','هودي عنابي برسمة تراثية كريمية على الظهر. من البيت إلى الجامعة.'),sizes:['XS','S','M','L','XL','2XL']},
{id:'tote',name:P('The Ahlan Tote','حقيبة أهلاً'),price:20,desc:P('Natural canvas, expressive “أهلاً بيك” lettering, and a flowing Nile-inspired detail.','قماش طبيعي وعبارة «أهلاً بيك» ولمسة مستوحاة من النيل.'),sizes:['One size']}];}
let merchPick=null,merchColor='sand',merchSize='';
function merchPrice(n){return new Intl.NumberFormat(lang==='ar'?'ar-CA':'en-CA',{style:'currency',currency:'CAD',currencyDisplay:'code',maximumFractionDigits:0}).format(n)}
function merchSection(){if(!merchProducts.length)initializeMerch();return `<section class="section merch-section" id="merch" aria-labelledby="merch-title"><div class="sectiontop"><div><div class="eyebrow">${tr('Wear a little piece of home','خذ معك حتة من البيت')}</div><h2 id="merch-title">${tr('The SSO collection.','مجموعة المنظمة.')}</h2><p>${tr('Inspired by Sudan. Made for campus life.','مستوحاة من السودان ومن حياة الجامعة.')}</p></div><span class="merch-badge">${tr('COMING SOON','قريباً')}</span></div><p class="merch-disclaimer">${tr('Collection launching soon. Prices shown are estimates in CAD; final prices, sizing and pickup details will be announced before orders open.','المجموعة تُطلق قريباً. الأسعار تقديرية بالدولار الكندي؛ تُعلن الأسعار النهائية والمقاسات والاستلام قبل فتح الطلبات.')}</p><a class="button light cart-link" href="/sso-uofa/checkout.html">${tr('View bag & checkout','الحقيبة والدفع')} <span data-cart-count></span> </a><div class="merch-grid">${merchProducts.map(p=>`<article class="merch-card"><button class="merch-image" data-merch="${p.id}" aria-label="${tr('Preview','معاينة')} ${t(p.name)}"><img src="merch/${p.id}-studio.png" alt="${tr('Generated concept mockup:','معاينة تصميم مولدة:')} ${t(p.name)}" loading="lazy"></button><div class="merch-card-body"><div class="merch-card-title"><h3>${t(p.name)}</h3><span>${merchPrice(p.price)}</span></div><p>${t(p.desc)}</p><div class="merch-card-bottom"><small>${tr('Estimated price','سعر تقديري')}</small><button class="textlink" data-merch="${p.id}">${tr('Quick view','نظرة سريعة')} </button></div></div></article>`).join('')}</div><div class="merch-launch"><b>${tr('A small first drop.','إطلاق أول بسيط.')}</b><p>${tr('Watch for a limited pre-order window and campus pickup details. Orders are not open yet.','ترقّب فترة الطلب المسبق وتفاصيل الاستلام في الجامعة. لم تُفتح الطلبات بعد.')}</p></div></section>`}
function openMerch(id){merchPick=merchProducts.find(p=>p.id===id);merchColor=id==='hoodie'?'burgundy':'sand';merchSize=merchPick.sizes.length===1?merchPick.sizes[0]:'';drawMerchDialog();document.querySelector('#merch-dialog').showModal()}
function drawMerchDialog(){const p=merchPick,d=document.querySelector('#merch-dialog');d.innerHTML=`<button class="quick-close" id="merch-close" aria-label="${tr('Close quick view','إغلاق النظرة السريعة')}">×</button><div class="quick-layout"><a class="quick-photo" href="${productURL(p.id)}"><img src="merch/${p.id}-studio.png" alt="${t(p.name)}"></a><div class="quick-info"><div class="eyebrow">${tr('The collection · Quick view','المجموعة · نظرة سريعة')}</div><h2 id="merch-dialog-title">${t(p.name)}</h2><p class="merch-price">${merchPrice(p.price)} <small>${tr('estimated','تقديري')}</small></p><p>${t(p.desc)}</p><p class="product-colour"><i style="background:${p.id==='hoodie'?'#612c32':'#e5d7be'}"></i>${productColour(p)}</p>${sizeButtons(p,'quick')}<button class="button" id="merch-add" ${!merchSize?'disabled':''}>${tr('Add to bag','أضف للحقيبة')} </button><p id="merch-selection" role="status"></p><a id="quick-full" class="quick-full" href="${productURL(p.id)}">${tr('View full product · images & details','عرض المنتج · الصور والتفاصيل')} </a><small class="quick-availability">${tr('Collection launching soon. Orders are not open yet.','المجموعة تُطلق قريباً. لم تُفتح الطلبات بعد.')}</small></div></div>`;document.querySelector('#merch-close').onclick=()=>d.close();document.querySelectorAll('[data-quick-size]').forEach(b=>b.onclick=()=>{merchSize=b.dataset.quickSize;document.querySelector('#quick-full').href=productURL(p.id)+'&size='+encodeURIComponent(merchSize);document.querySelectorAll('[data-quick-size]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelector('#merch-add').disabled=false});document.querySelector('#merch-add').onclick=()=>{if(!p.sizes.includes(merchSize))return;addCartItem(p.id,merchSize);document.querySelector('#merch-selection').innerHTML=tr('Added to your bag.','أُضيف إلى حقيبتك.')+' <a href="/sso-uofa/checkout.html">'+tr('View bag','عرض الحقيبة')+' </a>'};}
function bindMerch(){document.querySelectorAll('[data-merch]').forEach(b=>b.onclick=()=>openMerch(b.dataset.merch));if(document.querySelector('#merch-dialog').open)drawMerchDialog()}
